import { Table, GenericColumn, StringColumn } from '../../db'

export const sys_auth_profile = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Authentication Configuration',
    name: 'sys_auth_profile',
    schema: {
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'Descriptive name of this authentication configuration',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
        }),
    },
    textIndex: true,
})
